
.scene-header {
  display: flex;
  align-items: center;
  gap: 12px;
  padding: 10px 16px;
}

.date-block {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 1px;
  flex-shrink: 0;
}

.date-label {
  font-family: var(--font-serif);
  font-size: 15px;
  font-weight: 500;
  color: var(--tide-deep);
  letter-spacing: 1px;
}

.date-weekday {
  font-size: 11px;
  color: var(--text-tertiary);
  font-family: var(--font-main);
  font-weight: 300;
}

.divider-wave {
  flex: 1;
  min-width: 40px;
  display: flex;
  align-items: center;
}

.wave-svg {
  width: 100%;
  height: 16px;
  color: var(--tide-light);
}

.scene-info {
  display: flex;
  flex-direction: column;
  align-items: flex-end;
  gap: 2px;
  flex-shrink: 0;
}

.location {
  display: flex;
  align-items: center;
  gap: 3px;
  font-size: 12px;
  color: var(--text-secondary);
}

.icon-pin {
  color: var(--tide-mid);
}

.weather {
  font-size: 11px;
  color: var(--text-tertiary);
  letter-spacing: 0.5px;
}
