
/* ====== 便签整体 ====== */
.wish-note {
  margin: 0 0 12px;
  position: relative;
  background:
    linear-gradient(
      to bottom,
      var(--sand-cream) 0%,
      #faf6ed 40%,
      #f8f3e8 100%
    );
  border-radius: 3px;
  padding: 20px 16px 12px;
  box-shadow:
    0 2px 8px rgba(139, 126, 106, 0.12),
    0 1px 3px rgba(139, 126, 106, 0.08),
    inset 0 0 0 1px rgba(196, 184, 154, 0.2);

  /* 便签纸微微倾斜 */
  transform: rotate(-0.5deg);
}

/* ====== 胶带 ====== */
.tape {
  position: absolute;
  top: -8px;
  left: 50%;
  transform: translateX(-50%) rotate(1deg);
  width: 60px;
  height: 16px;
  background: rgba(168, 212, 230, 0.35);
  border-radius: 2px;
  box-shadow: 0 1px 2px rgba(0, 0, 0, 0.06);

  &::after {
    content: '';
    position: absolute;
    inset: 1px;
    background: linear-gradient(
      135deg,
      rgba(255, 255, 255, 0.3) 0%,
      transparent 50%
    );
    border-radius: 1px;
  }
}

/* ====== 标题 ====== */
.note-header {
  display: flex;
  align-items: baseline;
  justify-content: space-between;
  margin-bottom: 12px;
  padding-bottom: 8px;
  border-bottom: 1px dashed var(--sand-light);
}

.note-title {
  font-family: var(--font-handwrite);
  font-size: 20px;
  color: var(--tide-deep);
  letter-spacing: 2px;
  line-height: 1.2;
}

.note-subtitle {
  font-family: var(--font-handwrite);
  font-size: 14px;
  color: var(--sand-dark);
  opacity: 0.7;
}

/* ====== 愿望行 ====== */
.note-body {
  display: flex;
  flex-direction: column;
  gap: 2px;
}

.wish-line {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 4px 2px;
  position: relative;
  transition: opacity 0.3s ease;

  /* 手写横线底纹 */
  &::after {
    content: '';
    position: absolute;
    bottom: 0;
    left: 26px;
    right: 0;
    height: 1px;
    background: repeating-linear-gradient(
      90deg,
      var(--sand-light) 0px,
      var(--sand-light) 4px,
      transparent 4px,
      transparent 8px
    );
    opacity: 0.3;
  }

  &.is-empty {
    opacity: 0.3;
  }

  &.is-done {
    opacity: 0.55;
  }

  &.is-active {
    .wish-name {
      color: var(--tide-deep);
    }
  }
}

/* ====== 复选框 ====== */
.wish-checkbox {
  flex-shrink: 0;
  display: flex;
  align-items: center;
  justify-content: center;
  color: var(--sand-dark);

  .is-done & {
    color: var(--sunset-warm);
  }

  .is-active & {
    color: var(--tide-mid);
  }

  .is-empty & {
    color: var(--sand-light);
  }
}

.checkbox-check {
  animation: drawCheck 0.4s ease forwards;
}

@keyframes drawCheck {
  from {
    stroke-dasharray: 30;
    stroke-dashoffset: 30;
  }
  to {
    stroke-dasharray: 30;
    stroke-dashoffset: 0;
  }
}

.checkbox-dot {
  animation: dotPulse 2s ease-in-out infinite;
}

@keyframes dotPulse {
  0%, 100% { opacity: 0.5; r: 3.5; }
  50% { opacity: 1; r: 4.5; }
}

/* ====== 愿望文字 ====== */
.wish-text {
  flex: 1;
  position: relative;
  min-width: 0;
  display: flex;
  align-items: center;
}

.wish-name {
  font-family: var(--font-handwrite);
  font-size: 16px;
  color: var(--text-primary);
  line-height: 1.6;
  letter-spacing: 1px;
  position: relative;
  z-index: 1;

  .is-done & {
    color: var(--sand-dark);
  }
}

/* 手绘划线 */
.strike-line {
  position: absolute;
  left: -2px;
  right: -2px;
  top: 0;
  bottom: 0;
  width: calc(100% + 4px);
  height: 100%;
  z-index: 2;
  pointer-events: none;
}

.wish-placeholder {
  font-family: var(--font-handwrite);
  font-size: 14px;
  color: var(--sand-light);
  letter-spacing: 6px;
}

/* ====== 日期 ====== */
.wish-date {
  flex-shrink: 0;
  font-family: var(--font-handwrite);
  font-size: 12px;
  color: var(--sand-dark);
  opacity: 0.6;
}

/* ====== 底部装饰 ====== */
.note-footer {
  margin-top: 8px;
  display: flex;
  justify-content: center;
}

.footer-wave {
  width: 80%;
  height: 6px;
}
